CREATE TABLE IF NOT EXISTS acrl_survey_years (
  survey_year SMALLINT NOT NULL,
  status VARCHAR(12) NOT NULL DEFAULT 'draft',
  source_file_name VARCHAR(255) NULL,
  source_sha256 CHAR(64) NULL,
  survey_prompt_count INT NOT NULL DEFAULT 0,
  trends_prompt_count INT NOT NULL DEFAULT 0,
  survey_item_count INT NOT NULL DEFAULT 0,
  trends_item_count INT NOT NULL DEFAULT 0,
  created_by VARCHAR(100) NOT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  published_by VARCHAR(100) NULL,
  published_at DATETIME NULL,
  PRIMARY KEY (survey_year),
  CONSTRAINT chk_acrl_year_status CHECK (status IN ('draft', 'published'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS acrl_questions (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  survey_year SMALLINT NOT NULL,
  sheet VARCHAR(8) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  question_id VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  part VARCHAR(1) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT '',
  section VARCHAR(120) NOT NULL,
  prompt TEXT NOT NULL,
  answer_type VARCHAR(16) NOT NULL,
  required_status VARCHAR(8) NOT NULL DEFAULT 'unknown',
  calculated_from TEXT NULL,
  survey_order INT NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_acrl_question (survey_year, sheet, question_id, part),
  KEY idx_acrl_questions_order (survey_year, sheet, survey_order),
  CONSTRAINT fk_acrl_question_year FOREIGN KEY (survey_year) REFERENCES acrl_survey_years(survey_year) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS acrl_question_links (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  previous_year SMALLINT NOT NULL,
  current_year SMALLINT NOT NULL,
  sheet VARCHAR(8) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  previous_question_id VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  previous_part VARCHAR(1) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT '',
  current_question_id VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  current_part VARCHAR(1) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT '',
  match_kind VARCHAR(16) NOT NULL,
  score DECIMAL(5,4) NOT NULL DEFAULT 0,
  decision VARCHAR(12) NOT NULL,
  decided_by VARCHAR(100) NOT NULL,
  decided_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_acrl_question_link (previous_year, current_year, sheet, previous_question_id, previous_part, current_question_id, current_part),
  KEY idx_acrl_links_current (current_year, sheet),
  CONSTRAINT chk_acrl_link_decision CHECK (decision IN ('approved', 'rejected')),
  CONSTRAINT fk_acrl_link_previous FOREIGN KEY (previous_year, sheet, previous_question_id, previous_part) REFERENCES acrl_questions(survey_year, sheet, question_id, part) ON DELETE CASCADE,
  CONSTRAINT fk_acrl_link_current FOREIGN KEY (current_year, sheet, current_question_id, current_part) REFERENCES acrl_questions(survey_year, sheet, question_id, part) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

