UNION ALL SELECT 2024 AS survey_year, 'published' AS status, NULL AS source_file_name, NULL AS source_sha256, 69 AS survey_prompt_count, 9 AS trends_prompt_count, 79 AS survey_item_count, 9 AS trends_item_count, 'migration:054' AS created_by, '2026-10-26 14:24:58' AS created_at, 'migration:054' AS published_by, '2026-10-26 14:24:58' AS published_at FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM acrl_survey_years existing WHERE existing.survey_year = 2024) UNION ALL SELECT 2025 AS survey_year, 'published' AS status, NULL AS source_file_name, NULL AS source_sha256, 69 AS survey_prompt_count, 15 AS trends_prompt_count, 79 AS survey_item_count, 15 AS trends_item_count, 'migration:054' AS created_by, '2026-10-26 14:24:58' AS created_at, 'migration:054' AS published_by, '2026-10-26 14:24:58' AS published_at FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM acrl_survey_years existing WHERE existing.survey_year = 2025);
